$ErrorActionPreference = "Stop"
if ($PSVersionTable.PSVersion -ge [version]'7.4.0') {$PSNativeCommandUseErrorActionPreference = $true}
filter Indent {if ($_ -eq "") {""} else {"  $_"}}
$v = asyncutils -v
$m = "`n.. note:: Preview generated by scripts/generate.ps1 at $([datetime]::UtcNow.ToString("yyyy-MM-dd HH:mm:ss")) UTC. DO NOT COMMIT."
"Bug Reporting`n=============`n`n.. version-added:: 1.1.3`n`n..highlight:: text`n`nThe ````asyncutils bug```` command, which calls :func:``~asyncutils.cli.bug`` under the hood, is used to assist ticket submission to the GitHub issue tracker for :mod:``asyncutils``. It utilizes the GitHub issue form schema to grab environment information the bug report needs, such that you need not enter them manually, making for better UX and easier debugging.`n`nThis is the help output for the bug report subcommand, as of $v::`n`n$(asyncutils bug -h | Indent | Out-String)$m" | Out-File "docs/source/bug-help.rst" -Encoding utf8
"CLI Usage`n=========`n`n..highlight:: text`n`nThis is the output of ````asyncutils --help````, as of $v::`n`n$(asyncutils -h | Indent | Out-String)$m" | Out-File "docs/source/help.rst" -Encoding utf8
"$(Get-Content -Path "assets\mkpream.rst" | Out-String)`nBelow is the Makefile help as of $v::`n`n$(Get-Content -Path "assets\mkhelp.txt" | Indent | Out-String)$m" | Out-File "docs/source/makefile-usage.rst" -Encoding utf8
curl.exe -Z -o docs/source/ai-use.md https://raw.githubusercontent.com/jonathandung/.github/main/AI_USAGE_POLICY.md -o docs/source/conduct.md https://raw.githubusercontent.com/jonathandung/.github/main/CODE_OF_CONDUCT.md -o docs/source/contributing.md https://raw.githubusercontent.com/jonathandung/.github/main/CONTRIBUTING.md -o docs/source/governance.md https://raw.githubusercontent.com/jonathandung/.github/main/GOVERNANCE.md
@("CHANGELOG.md:changelog.md","EXAMPLES.rst:examples.rst","ROADMAP.md:roadmap.md","SECURITY.md:security.md","SUPPORT.md:support.md") | ForEach-Object {$s,$d = $_ -split ':',2; Copy-Item "$s" "docs/source/$d"}
